WITH lines AS (SELECT id, customer_id, created_at, EXPLODE_OUTER(coupon_codes) AS element FROM carts) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(*) AS cnt, SIZE(COLLECT_SET(element)) AS num_elements, COUNT(*) AS num_rows, SORT_ARRAY(COLLECT_SET(element)) AS element_list, COUNT_IF(element = 'VIP') AS vip_events FROM lines GROUP BY GROUPING SETS ((DATE_TRUNC('HOUR', created_at), DATE_TRUNC('DAY', created_at)), (DATE_TRUNC('HOUR', created_at)));
